require 'json';require 'fileutils';require 'digest'
root=File.expand_path('..',__dir__);stage=File.join(root,'test-move/xcpdk');official=File.join(root,'server/XCPDK');staged=Dir[File.join(stage,'**/*')].select{|p|File.file?(p)};formal=Dir[File.join(official,'**/*')].select{|p|File.file?(p)&&!p.include?('/target/')&&!p.include?('/build/')};matrix=staged.map{|p|rel=p.delete_prefix(stage+'/');target=File.join(official,rel);{path:rel,status:File.exist?(target)?(Digest::SHA256.file(p)==Digest::SHA256.file(target)?'identical':'different'):'missing',target:target.delete_prefix(root+'/')}};scanned=Dir[File.join(root,'{pom.xml,server/**/pom.xml,server/**/src/**/*,deploy/**/*}')].select{|p|File.file?(p)&&!p.include?('/target/')&&!p.include?('/build/')}
checks={stage_has_no_unclassified_file:staged.empty?||matrix.all?{|r|%w[identical migrated approved-obsolete].include?(r[:status])},formal_module_present:formal.any?{|p|p.end_with?('.java')},no_stage_runtime_reference:scanned.none?{|p|File.read(p).include?('test-move/xcpdk')}};result={task:'STAGE02',passed:checks.values.all?,checks:checks,stagedFiles:staged.length,formalFiles:formal.length,matrix:matrix};out=File.join(root,'work/audit/stage02-xcpdk.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(result)+"\n");puts "STAGE02 #{result[:passed]?'passed':'failed'}: #{staged.length} staged files, #{formal.length} formal files";exit(result[:passed]?0:1)
